from pathlib import Path
path = Path('shipkit/versioning.py')
path.write_text('''"""Helpers for selecting the latest dotted numeric release version."""


def _version_key(version):
    """Return a tuple of integer components for a dotted numeric version."""
    return tuple(int(component) for component in version.split("."))


def latest_version(versions):
    """Return the highest version from an iterable of dotted version strings."""
    if not versions:
        raise ValueError("versions cannot be empty")
    return max(versions, key=_version_key)
''')
